const LEVELS = ["debug", "info", "warn", "error"];
const LEVEL_ORDER = Object.fromEntries(LEVELS.map((name, index) => [name, index]));

let currentLevel = "info";

export function setLevel(level) {
  if (!(level in LEVEL_ORDER)) {
    throw new Error(`Unknown log level: ${level}`);
  }
  currentLevel = level;
}

export function getLevel() {
  return currentLevel;
}

function write(level, message) {
  if (LEVEL_ORDER[level] >= LEVEL_ORDER[currentLevel]) {
    console.error(message);
  }
}

export function debug(message) {
  write("debug", message);
}

export function info(message) {
  write("info", message);
}

export function warn(message) {
  write("warn", message);
}

export function error(message) {
  write("error", message);
}

export function log(message) {
  write("info", message);
}

import test from "node:test";
import assert from "node:assert/strict";
import {
  log,
  debug,
  info,
  warn,
  error,
  setLevel,
  getLevel,
} from "../lib/logger.mjs";

function capture(fn) {
  const original = console.error;
  const lines = [];
  console.error = (msg) => lines.push(msg);
  try {
    fn();
  } finally {
    console.error = original;
  }
  return lines;
}

test("default level is info", () => {
  setLevel("info");
  assert.equal(getLevel(), "info");
});

test("messages at or above the active level are emitted", () => {
  setLevel("info");
  const lines = capture(() => {
    info("info-msg");
    warn("warn-msg");
    error("error-msg");
  });
  assert.deepEqual(lines, ["info-msg", "warn-msg", "error-msg"]);
});

test("messages below the active level are suppressed", () => {
  setLevel("info");
  const lines = capture(() => debug("debug-msg"));
  assert.deepEqual(lines, []);
});

test("setLevel('debug') re-enables debug output", () => {
  setLevel("debug");
  const lines = capture(() => debug("debug-msg"));
  assert.deepEqual(lines, ["debug-msg"]);
  setLevel("info");
});

test("log() still emits at the default level", () => {
  setLevel("info");
  const lines = capture(() => log("plain-msg"));
  assert.deepEqual(lines, ["plain-msg"]);
});

test("setLevel rejects unknown levels", () => {
  assert.throws(() => setLevel("verbose"));
});
